"""Revalidate local receipt evidence and public Windows job status separately."""
import json,argparse,ast
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--local-fixture',type=Path,default=Path('/data/raw/g74-local-fixture.json'));p.add_argument('--runs',type=Path,default=Path('/data/raw/g74-github-run-api.json'));p.add_argument('--jobs',type=Path,default=Path('/data/raw/g74-github-jobs-api.json'));p.add_argument('--artifacts',type=Path,default=Path('/data/raw/g74-github-artifacts-api.json'));p.add_argument('--test-source',type=Path,default=Path('/data/g74-build/analysis-tools/two-host-pre-send-g74/test_pre_send_gate.py'));p.add_argument('--out',type=Path,default=Path('/data/analysis'));a=p.parse_args();a.out.mkdir(parents=True,exist_ok=True)
j=json.loads(a.local_fixture.read_text());run=next(r for r in json.loads(a.runs.read_text())['workflow_runs'] if r['id']==40312354354);jobs=json.loads(a.jobs.read_text())['jobs'];artifacts=json.loads(a.artifacts.read_text())['artifacts']
assert run['head_sha']=='c56b70bcc6178fe61be3df3a8cab22b4e873bd35' and run['status']=='completed' and run['conclusion']=='success' and run['run_attempt']==1
assert len(jobs)==1 and jobs[0]['id']==121536404373 and jobs[0]['conclusion']=='success'
for name in ['Verify pinned Git-blob bases and materialize local prototype','Parse and test admission and canonicalization','Local-only physical upstream receipt controls, no installer']:
 assert next(s for s in jobs[0]['steps'] if s['name']==name)['conclusion']=='success'
assert len(artifacts)==1 and artifacts[0]['id']==12644549561 and artifacts[0]['digest']=='sha256:c7aa10519204dae7a8244035ab6293bd6f73608a3d843164e7f28ea4f511525a'
assert j['run_id']==j['source_commit']=='local' and j['passed'] and len(j['rows'])==j['case_count']==17
assert j['loopback_sink_only'] and not any(j[k] for k in ['external_service_used','installer_started','firewall_changed','certificate_trust_changed','transparent_proxy_implemented','production_integration_complete','all_outbound_paths_covered','raw_values_exported','fingerprinting_absence_proven'])
rows=j['rows'];assert len({r['case'] for r in rows})==len(rows)
assert all(r['passed'] and r['no_upstream_connection_before_complete_admission'] for r in rows)
allowed=[r for r in rows if r['expected_allowed']];denied=[r for r in rows if not r['expected_allowed']]
assert len(allowed)==3 and len(denied)==14
assert all(r['upstream_connection_attempts']==r['upstream_accepted_connections']==1 and r['upstream_receipt_exact_canonical_request'] for r in allowed)
assert all(r['upstream_connection_attempts']==r['upstream_accepted_connections']==0 and r['denied_zero_upstream_connections_and_bytes'] for r in denied)
new_tests=sum(isinstance(n,ast.FunctionDef) and n.name.startswith('test_') for n in ast.walk(ast.parse(a.test_source.read_text())));assert new_tests==30
facts={'source_commit':run['head_sha'],'run_id':str(run['id']),'job_id':str(jobs[0]['id']),'run_attempt':run['run_attempt'],'Windows_job_success':True,'Windows_test_step_success':True,'Windows_loopback_fixture_step_success':True,'local_test_discovery_total':171,'local_Windows_specific_skips':1,'new_policy_unit_tests':new_tests,'local_physical_receipt_controls':len(rows),'local_positive_controls':len(allowed),'local_negative_controls':len(denied),'local_denied_controls_zero_upstream_connections':True,'local_positive_receipts_exact_canonical':True,'Windows_artifact_id':str(artifacts[0]['id']),'Windows_artifact_API_digest':artifacts[0]['digest'],'Windows_artifact_bytes_downloaded':False,'Windows_artifact_digest_locally_rechecked':False,'Windows_raw_case_rows_individually_rechecked':False,'Windows_detailed_logs_downloaded':False,'Windows_evidence_limit':'public run/job API confirms source and successful guarded steps; artifact 401 and log 403 require authentication; individual rows and log count not independently loaded','target_runs_this_stage':0,'external_BattleNet_requests_this_stage':0,'firewall_changes_this_stage':False,'certificate_changes_this_stage':False,'new_runtime_destinations':False,'main_or_desktop_release_changed':False,'production_integration_complete':False,'global_privacy_absence_proven':False,'prototype_input_contract':'one complete bounded plaintext HTTP/1.1 request from trusted adapter; no transparent proxy/TLS/OS-wide binding','raw_case_rows_source':'local Git-blob-composed prototype only; not Windows runner artifact','comparison_plan':[{'finding':'pre-admission loopback physical receipt assertions','grain':'synthetic fixture case, not real installer request','disposition':'prose','reason':'functional equality and zero-side-effect assertions; not a measured trend or distribution'}]}
(a.out/'g74-evidence.json').write_text(json.dumps(facts,indent=2));(a.out/'g74-local-case-rows.json').write_text(json.dumps(rows));print(json.dumps({k:facts[k] for k in ['Windows_job_success','local_physical_receipt_controls','local_positive_controls','local_negative_controls','target_runs_this_stage']}))
